  S_WAIT_FOR_GROUND: begin 
  if(~dig & ground) begin 
  next_state = S_WALK_LEFT; 
  end else if(~dig & ~ground) begin 
  next_state = S_FALLING; 
  end else if(dig & ground) begin 
  next_state = S_DIGGING; 
  end else if(dig & ~ground) begin 
  next_state = S_WAIT_FOR_GROUND; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  S_DIGGING: begin 
  if(~dig & ~ground) begin 
  next_state = S_FALLING; 
  end else if(~dig & ground) begin 
  next_state = S_WALK_LEFT; 
  end else if(dig & ~ground) begin 
  next_state = S_DIGGING; 
  end else if(dig & ground) begin 
  next_state = S_DIGGING; 
  end else begin 
  next_state = present_state; 
  end 
  end 
  default: begin 
  next_state = present_state; 
  end 
  endcase 
  end 
  always @(posedge clk) begin 
  case(next_state) 
  S_WALK_LEFT: begin 
  walk_left <= 1'b1; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  S_WALK_RIGHT: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b1; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  S_FALLING: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b1; 
  digging <= 1'b0; 
  end 
  S_DIGGING: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b1; 
  end 
  S_WAIT_FOR_GROUND: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  default: begin 
  walk_left <= 1'b0; 
  walk_right <= 1'b0; 
  aaah <= 1'b0; 
  digging <= 1'b0; 
  end 
  endcase 
  end 
  endmodule

